package local.atmospherevisual;
import me.cryo.zombierool.gameplay.*;
import me.cryo.zombierool.client.*;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.fml.common.Mod;
@Mod("atmospherevisual")
public final class CombatEffectsVisualTest {
 final boolean bullets=System.getenv("ZR_REAL_BULLETS")!=null;
 final boolean kills=System.getenv("ZR_IMPACT_KILLS")!=null;
 final boolean scourge=System.getenv("ZR_SCOURGE_IMPACTS")!=null;
 boolean requested,done;int age,checks;volatile String failure;volatile java.util.UUID target;long slowest,total;int samples;long lastFrame;final java.util.List<Double> frameMs=new java.util.ArrayList<>();
 public CombatEffectsVisualTest(){MinecraftForge.EVENT_BUS.addListener(this::tick);MinecraftForge.EVENT_BUS.addListener(this::frame);}
 void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;System.out.println("ATMOSPHERE VISUAL CHECK: "+text);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> action){var mc=Minecraft.getInstance();mc.getSingleplayerServer().execute(()->{try{action.accept(mc.getSingleplayerServer().getPlayerList().getPlayers().get(0));}catch(Throwable e){failure=e.toString();e.printStackTrace();}});}
 void checkSky(java.lang.reflect.Method method,net.minecraft.resources.ResourceLocation sky)throws Exception{if(!(Boolean)method.invoke(null,sky))throw new AssertionError("Lost sky resource");}
 void shot(String name)throws Exception{var mc=Minecraft.getInstance();try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(java.nio.file.Path.of(System.getProperty("atmosphere.output"),name+".png"));}}
 void frame(TickEvent.RenderTickEvent e){if(e.phase!=TickEvent.Phase.START)return;long now=System.nanoTime();if(age>=(kills?60:75)&&age<190&&lastFrame!=0)frameMs.add((now-lastFrame)/1e6);lastFrame=now;}
 void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;try{
 if(failure!=null)throw new AssertionError(failure);if(!requested){requested=true;mc.options.pauseOnLostFocus=false;org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().getWindow());mc.createWorldOpenFlows().loadLevel(mc.screen,"AtmosphereFixture");return;}if(mc.level==null||mc.player==null||mc.isPaused())return;age++;
 if(age==30)server(p->{var l=p.serverLevel();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.teleportTo(l,.5,65,25,180,8);l.setDayTime(6000);MapAtmosphere.get(l).configure(l,scourge?MapAtmosphere.preset("halo_zenith"):MapAtmosphere.defaults());var gun=me.cryo.zombierool.core.system.WeaponFacade.createWeaponStack(scourge?"mp5":"scarh",!scourge,p);check(me.cryo.zombierool.core.system.WeaponFacade.isWeapon(gun),"Impact test uses a real weapon stack");check(me.cryo.zombierool.core.system.WeaponFacade.isPackAPunched(gun)==!scourge,"Impact test uses the requested upgrade state");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,gun);var zombie=new me.cryo.zombierool.entity.ZombieEntity(me.cryo.zombierool.init.ZombieroolModEntities.ZOMBIE.get(),l);if(scourge)zombie.setCustomSkin("@preset/zombies/scourge/1");zombie.setPos(.5,65,15);zombie.setNoAi(true);zombie.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(1000000);zombie.setHealth(1000000);l.addFreshEntity(zombie);target=zombie.getUUID();if(kills){p.setGameMode(net.minecraft.world.level.GameType.ADVENTURE);p.getAbilities().invulnerable=true;p.onUpdateAbilities();for(int i=0;i<100;i++)me.cryo.zombierool.entity.BloodDecalEntity.pool(l,(i%10)-4.5,65,11+i/10,1);l.setBlock(new BlockPos(4,65,20),me.cryo.zombierool.block.system.FurnitureSystem.ALL.get("wow_bone_pile").get().defaultBlockState(),3);}});
 if(age>=70&&age<190&&age%3==0)server(p->{var zombie=(net.minecraft.world.entity.LivingEntity)p.serverLevel().getEntity(target);if(kills){if(bullets&&samples>0)check(zombie!=null&&!zombie.isAlive(),"TaCZ projectile collision kills its target");if(samples==0&&zombie!=null)zombie.discard();var fresh=me.cryo.zombierool.init.ZombieroolModEntities.ZOMBIE.get().create(p.serverLevel());fresh.setPos(.5+(samples%3-1)*.6,65,15);if(samples%4!=0)fresh.setCustomSkin("@preset/zombies/scourge/"+new int[]{1,5,7}[samples%3]);fresh.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(4);fresh.setHealth(4);p.serverLevel().addFreshEntity(fresh);zombie=fresh;target=fresh.getUUID();}if(scourge&&!kills)((me.cryo.zombierool.entity.ZombieEntity)zombie).setCustomSkin("@preset/zombies/scourge/"+new int[]{1,5,7}[Math.min(2,(age-70)/40)]);var damage=p.damageSources().playerAttack(p);long begin=System.nanoTime();float amount=6.5f;
 if(bullets){var stack=p.getMainHandItem();var gun=com.tacz.guns.api.item.IGun.getIGunOrNull(stack);var id=gun.getGunId(stack);var index=com.tacz.guns.api.TimelessAPI.getCommonGunIndex(id).orElseThrow();var bullet=new com.tacz.guns.entity.EntityKineticBullet(p.serverLevel(),p,stack,id,index.getGunData().getAmmoId(),true,index.getGunData(),index.getBulletData());var start=p.getEyePosition();bullet.setPos(start);bullet.setDeltaMovement(zombie.position().add(0,.9,0).subtract(start).normalize().scale(12));p.serverLevel().addFreshEntity(bullet);samples++;return;}
 if(me.cryo.zombierool.core.system.WeaponFacade.isTaczWeapon(p.getMainHandItem())){var id=com.tacz.guns.api.item.IGun.getIGunOrNull(p.getMainHandItem()).getGunId(p.getMainHandItem());var hit=new com.tacz.guns.api.event.common.EntityHurtByGunEvent.Pre(p,zombie,p,id,id,10,org.apache.commons.lang3.tuple.Pair.of(damage,damage),false,1,net.minecraftforge.fml.LogicalSide.SERVER);MinecraftForge.EVENT_BUS.post(hit);amount=hit.getBaseAmount();}
 me.cryo.zombierool.core.manager.DamageManager.applyDamage(zombie,damage,amount);if(kills)check(!zombie.isAlive(),"A real Scourge death runs its gore and corpse path");long elapsed=System.nanoTime()-begin;if(samples++>3){slowest=Math.max(slowest,elapsed);total+=elapsed;}});
 if(age==195){if(bullets){var sky=new net.minecraft.resources.ResourceLocation(MapAtmosphereClient.settings().getString("skyTexture"));var lookup=MapAtmosphereClient.class.getDeclaredMethod("skyAvailable",net.minecraft.resources.ResourceLocation.class);lookup.setAccessible(true);check((Boolean)lookup.invoke(null,sky),"Zenith sky resolves for real projectile test");long start=System.nanoTime();for(int i=0;i<10000;i++)checkSky(lookup,sky);double time=(System.nanoTime()-start)/1e6;System.out.println("SKY LOOKUP 10000 cached calls ms="+time);check(time<100,"Repeated sky checks avoid per-particle filesystem probes");var reset=MapAtmosphereClient.class.getDeclaredMethod("invalidateSkyLookup");reset.setAccessible(true);reset.invoke(null);check((Boolean)lookup.invoke(null,sky),"Sky resolves again after cache invalidation");}if(kills){var block=me.cryo.zombierool.block.system.FurnitureSystem.ALL.get("wow_bone_pile").get();var model=mc.getBlockRenderer().getBlockModel(block.defaultBlockState());var quads=model.getQuads(block.defaultBlockState(),null,net.minecraft.util.RandomSource.create(1));check(!quads.isEmpty()&&quads.stream().noneMatch(q->q.getSprite().contents().name().toString().contains("missingno")),"Bone pile baked faces resolve real vanilla textures");}if(scourge){var tileField=BloodSurfaceRenderer.class.getDeclaredField("TILES");tileField.setAccessible(true);var atlasField=BloodSurfaceRenderer.class.getDeclaredField("ATLASES");atlasField.setAccessible(true);int tiles=((java.util.Map<?,?>)tileField.get(null)).size(),pages=((java.util.List<?>)atlasField.get(null)).size();System.out.println("BLOOD ATLAS tiles="+tiles+" pages="+pages);check(tiles>0&&pages>0&&pages<tiles,"Blood surfaces share atlas pages without reducing tile resolution");}System.out.println("WEAPON IMPACT samples="+samples+(bullets?" path=TaCZ_projectile":" max_ms="+slowest/1e6+" total_ms="+total/1e6));check(samples>=30,"Repeated weapon impacts complete");shot("scarh-electric-impact");frameMs.sort(Double::compare);System.out.println("WEAPON FRAME samples="+frameMs.size()+" p95_ms="+frameMs.get((int)(frameMs.size()*.95))+" max_ms="+frameMs.get(frameMs.size()-1));check(frameMs.get(frameMs.size()-1)<250,"Repeated weapon hit test avoids 250 ms client stalls");}
 if(age==200){mc.particleEngine.setLevel(mc.level);server(p->{var z=p.serverLevel().getEntity(target);if(z!=null)z.discard();});}
 if(age==210)ClientWeaponVfxHandler.handleVfx("EXPLOSION",new net.minecraft.world.phys.Vec3(.5,65,20),new net.minecraft.world.phys.Vec3(.5,65,20),false,false);
 if(age==212)shot("grenade-flash");if(age==220)shot("grenade-smoke");
 if(age==240)ClientWeaponVfxHandler.handleVfx("FIRE_BURST",new net.minecraft.world.phys.Vec3(.5,65,20),new net.minecraft.world.phys.Vec3(.5,65,20),false,false);if(age==245)shot("molotov-burst");
 if(age==260){done=true;System.out.println("ATMOSPHERE VISUAL PASS: "+checks+" combat effects checks");mc.stop();}
 }catch(Throwable error){done=true;error.printStackTrace();System.out.println("ATMOSPHERE VISUAL FAIL: "+error);mc.stop();}}
}
